<script setup lang="ts">
import {computed,ref} from 'vue'
import {api} from '../api'
import {number,time} from '../format'
import PageIntro from '../components/PageIntro.vue'
type Result={period:string[];window:string;strategy:string;oiRequired:boolean;costMultiplier:number;trades:number;net:number;returnPercent:number;closedHourMaxDrawdownPercent:number;fees:number;fundingPaidSigned:number;incompletePathTrades:number;markProxyTrades:number;windowEndTrades:number;checks:{rawCandidates?:number;oiMissing?:number};bySymbol:{symbol:string;trades:number;net:number}[]}
type Report={version:string;generatedAt:string;symbols:number;hours:number;networkRequests:number;rulesSha256:string;rules:{limitations:string[]};results:Result[];verdict:string}
type Trade={symbol:string;openedAt:string;closedAt:string;entry:number;initialStop:number;targets:number[];targetBasis:string[];initialMargin:number;initialQty:number;estimatedLossWithBuffer:number;net:number;exits:{time:string;reason:string;price:number|null;quantity:number}[]}
const book=ref<{ledger:Trade[]}|null>(null);const bookError=ref('');const busy=ref(false);let generation=0
const recent=computed(()=>book.value?.ledger.slice(-20).reverse()??[])
const reason=(v:string)=>({structure_stop:'结构/跟踪止损',liquidation_stress:'强平压力情景',partial_1:'第一批减仓',partial_2:'第二批减仓',gap_resume_exit:'缺口恢复后退出',time_exit:'持有时间退出',window_end_exit:'期末模型平仓',data_missing_collateral_stress:'末端数据缺失：剩余保证金全损压力情景'}[v]??v)
async function choose(r:Result){chosen.value=r;book.value=null;bookError.value='';busy.value=true;const id=++generation;try{const key=`${r.period[0]}-${r.strategy}-${r.oiRequired?'oi':'price'}-cost${r.costMultiplier}`;const result=await api<{ledger:Trade[]}>(`/api/research/backtest/${key}`);if(id===generation)book.value=result}catch(e){if(id===generation)bookError.value=e instanceof Error?e.message:String(e)}finally{if(id===generation)busy.value=false}}
const data=ref<Report|null>(null);const error=ref('');const chosen=ref<Result|null>(null)
api<Report>('/api/research/backtest').then(r=>{data.value=r}).catch(e=>{error.value=e.message})
</script>
<template><PageIntro eyebrow="STRUCTURE R1 · OFFLINE DIAGNOSTICS" title="先核对执行，再判断规则。" description="两套策略、结构止损、分批退出与成本压力测试。所有结果均为历史假设。"/><p v-if="error" class="radar-notice">{{error}}</p><template v-if="data"><p class="radar-notice">{{data.verdict}} 自动模拟开仓仍关闭。</p><p>{{data.symbols}}个合约 · {{number(data.hours,0)}}根小时K线 · 本轮下载请求 {{data.networkRequests}} · {{time(data.generatedAt)}}。每行是独立1000 USDT账户，不能相加；BTC/ETH也参与本次选中样本组合。</p><div class="provider-grid"><section class="detail"><h2>A · 提前埋伏量价代理</h2><p>72h区间收敛、靠近区间上部、成交增量，等待支撑与合理风险空间。另设OI确认版本：历史缺失就跳过。</p></section><section class="detail"><h2>B · 涨幅候选代理</h2><p>24h上涨8%～40%，放量突破72h高点、收盘靠近小时高位。尚未还原当时全市场榜单，不能叫完整涨幅榜策略回测。</p></section></div><section class="detail"><h2>入场与退出规则</h2><p>闭合信号后的下一小时开盘加滑点。止损取已确认支撑减0.5 ATR；保证金最多100、10倍逐仓、最多两笔，每笔计划风险最多10且不超过权益1%。合理止损与强平安全空间冲突则跳过。</p><p>优先在当时已确认的压力处分批减原始数量30%＋30%；无可用压力时明确用2R/4R作风险释放投影。剩余40%用入场ATR的3倍跟踪，从下一小时才生效。小时内先后未知时采用强平压力优先、止损优先的保守顺序。</p><p>手续费与滑点每边各0.05%，同时测试两倍成本。资金费按实际结算率计入，但结算价格可能用小时价格代理；维持保证金假设0.5%，不是交易所真实分层规则。日损达到30或时段权益回撤达到15%停止新开仓。</p></section><section class="detail"><h2>按时期与成本检查</h2><p>三个时期均已看过，只是按时间分段诊断，没有真正未参与研究的留出。回撤仅为小时权益及期末结算，盘中风险可能更大。点击行查看覆盖与标的贡献。</p><div class="table-scroll"><table><thead><tr><th>时段</th><th>策略</th><th>OI</th><th>成本</th><th>交易</th><th>净额USDT</th><th>回撤</th></tr></thead><tbody><tr v-for="(r,i) in data.results" :key="i" @click="choose(r)"><td><button class="text-button" @click.stop="choose(r)">{{r.window}}</button></td><td>{{r.strategy.toUpperCase()}}</td><td>{{r.oiRequired?'确认':'基线'}}</td><td>{{r.costMultiplier}}倍</td><td>{{r.trades}}</td><td>{{number(r.net,2)}}</td><td>{{number(r.closedHourMaxDrawdownPercent,2)}}%</td></tr></tbody></table></div></section><section v-if="chosen" class="detail"><h2>{{chosen.window}} · {{chosen.strategy.toUpperCase()}} · {{chosen.oiRequired?'OI确认':'量价基线'}} · {{chosen.costMultiplier}}倍成本</h2><p>原始候选 {{chosen.checks.rawCandidates??0}}，其中OI缺失 {{chosen.checks.oiMissing??0}}；路径缺失交易 {{chosen.incompletePathTrades}}，使用标记价代理交易 {{chosen.markProxyTrades}}，期末模型平仓 {{chosen.windowEndTrades}}。</p><p>手续费 {{number(chosen.fees,2)}}，资金费净支出 {{number(chosen.fundingPaidSigned,2)}} USDT（负数是收取）。0笔交易的净额0不能当作有效验证。</p><div class="table-scroll"><table><thead><tr><th>标的</th><th>交易</th><th>净额</th></tr></thead><tbody><tr v-for="s in chosen.bySymbol" :key="s.symbol"><td>{{s.symbol}}</td><td>{{s.trades}}</td><td>{{number(s.net,2)}}</td></tr></tbody></table></div></section><section v-if="chosen" class="detail"><h2>逐笔假设成交 · 最近20笔</h2><p v-if="busy">正在读取本地账本，不访问交易所。</p><p v-if="bookError" class="radar-notice">{{bookError}}</p><p v-if="book&&!recent.length">此变体没有成交，不能据此认定有效或安全。</p><details v-for="(p,i) in recent" :key="i"><summary>{{p.symbol}} · {{time(p.openedAt)}} · 净额 {{number(p.net,2)}} USDT</summary><p>假设入场 {{number(p.entry,6)}}；初始结构止损 {{number(p.initialStop,6)}}；数量 {{number(p.initialQty,6)}}；保证金 {{number(p.initialMargin,2)}}；计划风险含缓冲 {{number(p.estimatedLossWithBuffer,2)}} USDT。风险预算不是实际最大损失保证。</p><p>第一目标 {{number(p.targets[0],6)}}（{{p.targetBasis[0]==='confirmed_pressure'?'已确认历史压力':'2R风险释放投影'}}）；第二目标 {{number(p.targets[1],6)}}（{{p.targetBasis[1]==='confirmed_pressure'?'已确认历史压力':'风险投影'}}）。</p><p v-for="(e,j) in p.exits" :key="j">{{time(e.time)}} · {{reason(e.reason)}} · 价格 {{number(e.price,6)}} · 数量 {{number(e.quantity,6)}}</p></details><p>小时内触发时刻不精确，退出时间标记其小时起点；期末/时间退出按小时终点记录。完整账本保存在本地研究目录。</p></section><section class="detail"><h2>为什么还不能开自动模拟</h2><p v-for="s in data.rules.limitations" :key="s">{{s}}</p><p>参数文件及引擎均留SHA256，不按这次结果挑选更好看的参数。应补连续OI、失败样本全集与全市场历史排行，再登记前瞻验证期。</p><small>规则 SHA256 {{data.rulesSha256}}</small></section></template></template>
